def clear_auction_sell_state(user_id):
    """Canonical idempotent cleanup for every auction sell input state."""
    for state_name in (
        "AUCTION_SELL_STATE",
        "AUCTION_SELL_STATE_V2",
        "AUCTION_SELL_INLINE_STATE",
        "AUCTION_SELL_REVIEW_STATE",
