        return "👥 Підходить класам: усім класам"
    if not allowed:
        return "👥 Підходить класам: не визначено"
    names = [str(CLASS_CONFIGS.get(key, {}).get("name", key)) for key in allowed]
    return f"👥 Підходить класам: {', '.join(names)}"

