                        return "броня не підходить класу"

                    if real_slot_key == "main_hand":
                        return "зброя не підходить класу"

                    if real_slot_key == "off_hand":
                        return "предмет для другої руки не підходить класу"

            except Exception:
                pass

        return "не підходить новому класу"

