def get_pve_skill_action_state(user_id, mob, skill):
    """Return current PvE skill UI state without mutating DB or combat state."""
    del user_id
    mob = mob or {}
    skill = skill or {}
    name = str(skill.get("name") or skill.get("key") or "Навичка")
    key = str(skill.get("key") or "")

    cooldowns = mob.get("skill_cooldowns") or {}
    cooldown = max(0, int(cooldowns.get(key, 0) or 0))
    if cooldown > 0:
        return _state(
            skill, False, "cooldown",
            f"⏳ {name} · ще {_turns_uk(cooldown)}",
            f"⏳ {name} ще перезаряджається. Залишилось: {_turns_uk(cooldown)}.",
            remaining=cooldown,
        )

    player_stunned = max(0, int(mob.get("player_stunned_turns", 0) or 0))
    player_effects = mob.get("player_effects") or {}
    controlled = player_stunned > 0 or any(
        str(effect.get("type") or "").lower() in {"stun", "silence", "control"}
        and int(effect.get("turns", 0) or 0) > 0
        for effect in player_effects.values()
        if isinstance(effect, dict)
    )
    if controlled:
        return _state(
            skill, False, "control_state",
            f"🔒 {name} · зараз недоступна",
            f"🔒 {name} зараз недоступна через ефект контролю.",
        )

    cost_type = str(skill.get("cost_type") or "")
    cost = get_pve_effective_skill_cost(mob, skill)

    if cost_type == "rage":
        current = max(0, int(mob.get("player_rage", 0) or 0))
        if current < cost:
            return _state(skill, False, "not_enough_rage",
                          f"🔒 {name} · потрібно {cost} Люті",
                          f"🔴 Недостатньо Люті для {name}. Потрібно: {cost}, доступно: {current}.",
                          required=cost, available_amount=current)

    elif cost_type == "rage_all_min":
        required = max(0, int(skill.get("min_cost", 30) or 30))
        current = max(0, int(mob.get("player_rage", 0) or 0))
        if current < required:
            return _state(skill, False, "not_enough_rage",
                          f"🔒 {name} · потрібно {required} Люті",
                          f"🔴 Недостатньо Люті для {name}. Потрібно мінімум: {required}, доступно: {current}.",
                          required=required, available_amount=current)

    elif cost_type in {"combat_energy", "combat_energy_combo"}:
        current = max(0, int(mob.get("player_combat_energy", 0) or 0))
        maximum = max(0, int(mob.get("player_max_combat_energy", 100) or 100))
        projected = min(maximum, current + 20)
        if projected < cost:
            return _state(skill, False, "not_enough_combat_energy",
                          f"🔒 {name} · потрібно {cost} Енергії",
                          f"🟡 Недостатньо Енергії для {name}. Потрібно: {cost}, на початку ходу буде доступно: {projected}.",
                          required=cost, available_amount=projected)
        if cost_type == "combat_energy_combo":
            required_combo = max(1, int(skill.get("min_combo", 1) or 1))
            combo = max(0, int(mob.get("player_combo_points", 0) or 0))
            if combo < required_combo:
                return _state(skill, False, "not_enough_combo",
                              f"🔒 {name} · потрібно {required_combo} комбо",
                              f"⚔️ Недостатньо комбо для {name}. Потрібно: {required_combo}, доступно: {combo}.",
                              required=required_combo, available_amount=combo)

    elif cost_type == "mana":
        current = max(0, int(mob.get("player_mp", 0) or 0))
        maximum = max(0, int(mob.get("player_max_mp", 0) or 0))
        if skill.get("key") == "mage_arcane_flow" and maximum > 0 and current >= maximum:
            return _state(skill, False, "mana_already_full",
                          f"🔒 {name} · Мана вже повна",
                          "🔵 Мана вже повна.",
                          required=cost, available_amount=current, effective_cost=cost)
        if current < cost:
            return _state(skill, False, "not_enough_mana",
                          f"🔒 {name} · потрібно {cost} Мани",
                          f"🔵 Недостатньо Мани для {name}. Потрібно: {cost}, доступно: {current}.",
                          required=cost, available_amount=current, effective_cost=cost)

    return _state(skill, True, "ok", f"✨ {name}", "", effective_cost=cost)

def get_pvp_effective_skill_cost(skill: Mapping[str, Any], max_mp: Any) -> int:
    """Return canonical Mana cost or unchanged physical-resource cost."""
    if str(skill.get("cost_type") or "") == "mana":
        return calculate_mana_skill_cost(skill, max(0, int(max_mp or 0)))
    return max(0, int(skill.get("cost") or 0))

def projected_round_resource(participant: Mapping[str, Any]) -> int:
    value = int(participant.get("resource_value", participant.get("resource", 0)) or 0)
    if str(participant.get("resource_type") or "") in {"combat_energy", "combat_energy_combo"}:
        return min(PVP_COMBAT_ENERGY_MAX, value + 20)
    return value

def validate_pvp_action_choice(
    participant: Mapping[str, Any],
    action_type: str,
    skill_key: str | None = None,
    *,
    catalog: Mapping[str, tuple[dict[str, Any], ...]] | None = None,
) -> dict[str, Any]:
    """Prevalidate a UI action without mutating state or consuming the round.

    The pure round engine remains the final authority. This helper mirrors the
    engine's imminent start-of-round cooldown tick and Combat Energy regeneration
    so a choice accepted by the UI is not rejected later for stale resource data.
    """
    action_type = str(action_type or "")
    if action_type == "basic_attack":
        return {"success": True, "reason": "ok", "message": ""}
    if action_type != "skill" or not skill_key:
        return {"success": False, "reason": "invalid_action", "message": "❌ Невідома бойова дія. Оберіть іншу дію."}

    class_key = str(participant.get("class_key") or "")
    skill = get_production_pvp_skill(class_key, str(skill_key), catalog or load_production_pvp_skill_catalog())
    if not skill:
        return {"success": False, "reason": "unknown_skill", "message": "❌ Ця навичка не належить вашому класу. Оберіть іншу дію."}

    name = str(skill.get("name") or skill_key)
    cooldown = projected_round_cooldown(participant, str(skill_key))
    if cooldown > 0:
        return {
            "success": False,
            "reason": "skill_on_cooldown",
            "remaining": cooldown,
            "message": f"⏳ «{name}» ще відновлюється. Залишилося раундів: {cooldown}. Оберіть іншу дію.",
        }

    cost_type = str(skill.get("cost_type") or "")
    maximum_mp = max(0, int(participant.get("max_mp") or 0))
    cost = get_pvp_effective_skill_cost(skill, maximum_mp)
    resource = projected_round_resource(participant)
    mp = int(participant.get("mp") or 0)
    combo = int(participant.get("combo") or 0)

    if cost_type == "mana" and mp < cost:
        return {"success": False, "reason": "not_enough_mana", "required": cost, "available": mp, "message": f"🔷 Недостатньо мани для «{name}». Потрібно: {cost} MP, доступно: {mp} MP. Оберіть іншу дію."}
    if cost_type == "rage" and resource < cost:
        return {"success": False, "reason": "not_enough_rage", "required": cost, "available": resource, "message": f"🔥 Недостатньо Люті для «{name}». Потрібно: {cost}, доступно: {resource}. Оберіть іншу дію."}
    if cost_type == "rage_all_min":
        minimum = max(0, int(skill.get("min_cost") or 0))
        if resource < minimum:
            return {"success": False, "reason": "not_enough_rage", "required": minimum, "available": resource, "message": f"🔥 Недостатньо Люті для «{name}». Потрібно щонайменше: {minimum}, доступно: {resource}. Оберіть іншу дію."}
    if cost_type in {"combat_energy", "combat_energy_combo"} and resource < cost:
        return {"success": False, "reason": "not_enough_combat_energy", "required": cost, "available": resource, "message": f"⚡ Недостатньо Енергії для «{name}». Потрібно: {cost}, після відновлення доступно: {resource}. Оберіть іншу дію."}
    if cost_type == "combat_energy_combo":
        minimum_combo = int(skill.get("min_combo") or 1)
        if combo < minimum_combo:
            return {"success": False, "reason": "not_enough_combo", "required": minimum_combo, "available": combo, "message": f"🔗 Недостатньо комбо для «{name}». Потрібно: {minimum_combo}, доступно: {combo}. Оберіть іншу дію."}

    return {
        "success": True,
        "reason": "ok",
        "message": "",
        "skill": dict(skill),
        "projected_resource": resource,
        "projected_cooldown": cooldown,
    }

def _clamp(name, value):
    low, high, _, _ = PARAMETERS[name]
    return round(max(low, min(high, float(value))), 4)

def _actor(class_key, user_id, params):
    actor = build_real_actor(class_key, user_id)
    reference = PRODUCTION_REFERENCE[class_key]
    if class_key == "warrior":
        actor.physical_defense *= params["warrior_pdef"]
    elif class_key == "scout":
        actor.physical_attack = max(float(reference["str"]), float(reference["dex"]) * params["scout_dex_patk"])
    elif class_key == "rogue":
        actor.physical_attack = max(float(reference["str"]), float(reference["dex"]) * params["rogue_dex_patk"])
    elif class_key == "mage":
        actor.magical_attack *= params["mage_matk"]
    elif class_key == "knight":
        actor.physical_defense *= params["knight_pdef"]
    elif class_key == "priest":
        actor.magical_defense *= params["priest_mdef"]
    return actor

def _scale_priest_hot(actor, params, seen_hot):
    if actor.class_key != "priest" or "hot" not in actor.effects:
        return
    hot = actor.effects["hot"]
    marker = (actor.user_id, int(hot.get("source_id", actor.user_id)), int(hot.get("duration", 0)), float(hot.get("power", 0)))
    if marker in seen_hot:
        return
    original = float(hot.get("power", 0) or 0)
    hot["power"] = max(1, round(original * params["priest_hot"]))
    seen_hot.add((actor.user_id, int(hot.get("source_id", actor.user_id)), int(hot.get("duration", 0)), float(hot.get("power", 0))))

def _cap_winner(actor_a, actor_b):
    left = actor_a.hp / max(1, actor_a.max_hp)
    right = actor_b.hp / max(1, actor_b.max_hp)
    if abs(left - right) < 1e-12:
        return None
    return actor_a.user_id if left > right else actor_b.user_id

def _mutate(parent, rng, scale, guided=True):
    child = dict(parent["params"] if "params" in parent else parent)
    actions = _diagnose(parent) if guided and "class_average_win_rates" in parent else []
    if actions:
        rng.shuffle(actions)
        for name, direction in actions[: rng.randint(1, min(4, len(actions)))]:
            step = PARAMETERS[name][3] * scale * rng.uniform(0.6, 1.4)
            child[name] = _clamp(name, child[name] + direction * step)
    for _ in range(rng.randint(1, 4)):
        name = rng.choice(list(PARAMETERS))
        step = PARAMETERS[name][3] * scale * rng.gauss(0, 1)
        child[name] = _clamp(name, child[name] + step)
    return child

def _random_candidate(rng):
    candidate = {}
    for name, (low, high, neutral, _) in PARAMETERS.items():
        if rng.random() < 0.65:
            candidate[name] = _clamp(name, rng.gauss(neutral, (high - low) / 6))
        else:
            candidate[name] = _clamp(name, rng.uniform(low, high))
    return candidate

def run_optimizer(minutes=20, seed=14644, checkpoint_path=None, report_path=None, smoke=False):
    started=time.monotonic(); total_seconds=35.0 if smoke else max(0.05,float(minutes))*60; deadline=started+total_seconds*0.72
    rng=random.Random(int(seed)); checkpoint=Path(checkpoint_path) if checkpoint_path else None; history=[]; archive=[]; candidates_evaluated=0; generation=0
