def _run_pair_once(class_a, class_b, trials, seed):
    catalog = load_production_pvp_skill_catalog(); metrics = {class_a:_empty_metrics(), class_b:_empty_metrics()}
    wins = Counter(); draws = 0; terminal_reasons = Counter(); round_counts = []
