        EXISTS(SELECT 1 FROM equipment_slots es WHERE es.user_id=i.user_id AND es.inventory_id=i.id)
        FROM inventory i JOIN items it ON it.id=i.item_id WHERE i.id=?
    """,(equipment_inventory_id,)).fetchone()
