    armor_type = str(row[2] or "").strip().lower()
    if slot_key not in _RUNE_ARMOR_DISPLAY_SLOTS_10_9_2:
        return name
    type_label = _RUNE_ARMOR_DISPLAY_LABELS_10_9_2.get(armor_type, "")
