def build_execution_plan(config: AnalysisConfig, include_walls=True, include_inventory=None):
    config = config.validate()
    include_inventory = config.compare_inventory if include_inventory is None else bool(include_inventory)
    plan = set()

    def add_level(target_level, capacity):
        for character_class in config.classes:
            for profile in config.profiles:
                for seed in config.seeds:
                    plan.add(
                        ScenarioSpec(
                            character_class,
                            profile,
                            int(seed),
                            int(target_level),
                            int(capacity),
                            int(config.max_days),
                        )
                    )

    add_level(config.target_level, config.inventory_capacity)
    if include_walls:
        for target_level in range(2, config.target_level + 1):
            add_level(target_level, config.inventory_capacity)
    if include_inventory:
        add_level(config.target_level, 40)
        add_level(config.target_level, 60)
    return tuple(sorted(plan))

def execute_plan(root: Path, plan: Sequence[ScenarioSpec], workers=1, force=False, progress=None):
    root = Path(root)
    cache = ResultCache(root)
    workers = max(1, min(int(workers), 8))
    cached_specs = [] if force else [spec for spec in plan if cache.exists(spec)]
    pending = list(plan) if force else [spec for spec in plan if not cache.exists(spec)]
    total = len(plan)
    completed = len(cached_specs)
    started_at = time.monotonic()

    def notify(spec, source):
        nonlocal completed
        completed += 1
        elapsed = max(time.monotonic() - started_at, 0.001)
        fresh_done = max(completed - len(cached_specs), 0)
        fresh_total = len(pending)
        eta = 0.0
        if fresh_done and fresh_total > fresh_done:
            eta = elapsed / fresh_done * (fresh_total - fresh_done)
        if progress:
            progress(completed, total, spec, source, elapsed, eta)

    if progress and cached_specs:
        progress(completed, total, cached_specs[-1], "cache", 0.0, 0.0)

    try:
        if workers == 1:
            for spec in pending:
                _execute_scenario_worker(str(root), asdict(spec))
                notify(spec, "run")
        else:
            with ProcessPoolExecutor(max_workers=workers) as executor:
                futures = {
                    executor.submit(_execute_scenario_worker, str(root), asdict(spec)): spec
                    for spec in pending
                }
                for future in as_completed(futures):
                    spec = futures[future]
                    future.result()
                    notify(spec, "run")
    except KeyboardInterrupt:
        raise RuntimeError(
            "Analysis interrupted. Completed scenarios are checkpointed in the cache; "
            "rerun the same command to resume."
        )

    payloads = {spec: cache.load(spec) for spec in plan}
    return payloads, {
        "unique_scenarios": total,
        "cache_hits": len(cached_specs),
        "fresh_runs": len(pending),
        "workers": workers,
        "elapsed_seconds": round(time.monotonic() - started_at, 3),
    }

def _rows_for(payloads, config, target_level, capacity):
    rows = []
    for character_class in config.classes:
        for profile in config.profiles:
            for seed in config.seeds:
                spec = ScenarioSpec(
                    character_class,
                    profile,
                    int(seed),
                    int(target_level),
                    int(capacity),
                    int(config.max_days),
                )
                rows.append(payloads[spec])
    return rows

def build_balance_report(config, payloads, execution, include_inventory=None):
    include_inventory = config.compare_inventory if include_inventory is None else bool(include_inventory)
    groups = {}
    for character_class in config.classes:
        groups[character_class] = {}
        for profile in config.profiles:
            specs = [
                ScenarioSpec(character_class, profile, int(seed), config.target_level, config.inventory_capacity, config.max_days)
                for seed in config.seeds
            ]
            groups[character_class][profile] = aggregate_group([payloads[spec] for spec in specs])
    inventory_comparison = None
    if include_inventory:
        inventory_comparison = {
            str(capacity): aggregate_group(_rows_for(payloads, config, config.target_level, capacity))
            for capacity in (40, 60)
        }
    return {
        "schema": "rom.simulation.pve_balance.v1",
        "version": "13.7.2",
        "config": asdict(config),
        "config_fingerprint": config.fingerprint(),
        "run_count": len(config.classes) * len(config.profiles) * len(config.seeds),
        "cache_hits": execution["cache_hits"],
        "execution": execution,
        "groups": groups,
        "inventory_comparison": inventory_comparison,
        "database_writes": 0,
    }

def key_for(spec: ScenarioSpec):
        value = (
            f"{spec.character_class}|{spec.profile}|{spec.seed}|"
            f"{spec.target_level}|{spec.inventory_capacity}|{spec.max_days}"
        )
        return hashlib.sha256(value.encode()).hexdigest()

def add_level(target_level, capacity):
        for character_class in config.classes:
            for profile in config.profiles:
                for seed in config.seeds:
                    plan.add(
                        ScenarioSpec(
                            character_class,
                            profile,
                            int(seed),
                            int(target_level),
                            int(capacity),
                            int(config.max_days),
                        )
                    )

def choose_potion(self, hp: int, max_hp: int, mp: int, max_mp: int, mana_class: bool, hp_potions: Sequence[Dict[str, Any]], mp_potions: Sequence[Dict[str, Any]]) -> Optional[BehaviorDecision]:
        if max_hp > 0 and hp / max_hp < self.hp_potion_threshold and hp_potions:
            missing = max_hp - hp
            potion = min(hp_potions, key=lambda item: (max(0, int(item.get("restore", 0)) - missing), int(item.get("restore", 0))))
            return BehaviorDecision("use_hp_potion", "hp_below_40_percent", dict(potion))
        if mana_class and max_mp > 0 and mp / max_mp < self.mp_potion_threshold and mp_potions:
            missing = max_mp - mp
            potion = min(mp_potions, key=lambda item: (max(0, int(item.get("restore", 0)) - missing), int(item.get("restore", 0))))
            return BehaviorDecision("use_mp_potion", "mp_below_25_percent", dict(potion))
        return None

def maintenance(self, durability_values: Iterable[int], free_slots: int) -> Optional[BehaviorDecision]:
        values = list(durability_values)
        if values and min(values) <= self.repair_threshold:
            return BehaviorDecision("visit_city", "equipped_durability_at_or_below_15", {"min_durability": min(values)})
        if free_slots <= self.reserve_slots:
            return BehaviorDecision("visit_city", "inventory_reserve_reached", {"free_slots": free_slots})
        return None

def _mob_encounter_summary(events: list[Any]) -> dict[str, Any]:
    by_mob: dict[tuple[str, int, str], int] = {}
    by_level: dict[int, int] = {}
    by_delta = {-1: 0, 0: 0, 1: 0}
    by_attack: dict[str, int] = {}
    by_location: dict[str, int] = {}
    candidate_sizes: dict[int, int] = {}
    for event in events:
        details = dict(getattr(event, "details", {}) or {})
        if str(details.get("battle_outcome", "")) not in {"victory", "defeat", "escape"}:
            continue
        name = str(details.get("mob", "")); level = int(details.get("mob_level", details.get("level", 1))); kind = str(details.get("encounter_type", "normal"))
        by_mob[(name, level, kind)] = by_mob.get((name, level, kind), 0) + 1
        by_level[level] = by_level.get(level, 0) + 1
        delta = int(details.get("level_delta", level - int(details.get("player_level", details.get("level", level)))))
        if delta not in {-1, 0, 1}: raise RuntimeError(f"Mob level delta outside canonical range: {delta}")
        by_delta[delta] += 1
        attack = str(details.get("attack_type", "unknown")); by_attack[attack] = by_attack.get(attack, 0) + 1
        location = str(details.get("location_id", "unknown")); by_location[location] = by_location.get(location, 0) + 1
        size = int(details.get("candidate_count", 0)); candidate_sizes[size] = candidate_sizes.get(size, 0) + 1
    rows = [{"name": key[0], "level": key[1], "encounter_type": key[2], "count": count} for key, count in sorted(by_mob.items(), key=lambda row: (row[0][1], row[0][0], row[0][2]))]
    total = sum(row["count"] for row in rows)
    return {"total": total, "unique_mobs": len(rows), "by_mob": rows, "by_level": {str(k): v for k, v in sorted(by_level.items())}, "by_level_delta": {str(k): v for k, v in sorted(by_delta.items())}, "by_attack_type": dict(sorted(by_attack.items())), "by_location": dict(sorted(by_location.items())), "candidate_pool_sizes": {str(k): v for k, v in sorted(candidate_sizes.items())}}

def _contract_summary(events: list[Any]) -> tuple[dict[str, int], dict[str, int], list[dict[str, Any]]]:
    encounters = {"normal": 0, "elite": 0, "boss": 0}
    outcomes = {"victory": 0, "defeat": 0, "escape": 0}
    ledger: dict[tuple, dict[str, Any]] = {}
    for event in events:
        details = dict(getattr(event, "details", {}) or {})
        outcome = str(details.get("battle_outcome", ""))
        if outcome in outcomes:
            outcomes[outcome] += 1
            kind = str(details.get("encounter_type", "normal"))
            encounters[kind if kind in encounters else "normal"] += 1
        for item in details.get("loot_records", []) or []:
            key = (item.get("item_id"), item.get("name"), item.get("category"), item.get("rarity"))
            row = ledger.setdefault(key, {"item_id": item.get("item_id"), "name": item.get("name"), "category": item.get("category"), "rarity": item.get("rarity"), "slot_key": item.get("slot_key", ""), "item_level": int(item.get("item_level", 1)), "armor_type": item.get("armor_type", ""), "weapon_hands": int(item.get("weapon_hands", 1)), "stats": dict(item.get("stats", {})), "sell_price": float(item.get("sell_price", 0.0)), "created_ids": [], "found": 0, "awarded": 0, "lost_due_capacity": 0, "destinations": {}})
            row["created_ids"].extend(int(value) for value in item.get("created_ids", []) or [])
            for field in ("found", "awarded", "lost_due_capacity"): row[field] += int(item.get(field, 0))
            destination = str(item.get("destination", "unknown")); row["destinations"][destination] = row["destinations"].get(destination, 0) + int(item.get("found", 0))
