def build_progression_wall_report(config, payloads):
    levels = []
    for target_level in range(2, config.target_level + 1):
        groups = {}
        for character_class in config.classes:
            groups[character_class] = {}
            for profile in config.profiles:
                specs = [
                    ScenarioSpec(
                        character_class,
                        profile,
                        int(seed),
                        target_level,
                        config.inventory_capacity,
                        config.max_days,
                    )
                    for seed in config.seeds
                ]
                groups[character_class][profile] = aggregate_group([payloads[spec] for spec in specs])
        levels.append({"target_level": target_level, "groups": groups})

    transitions = []
    findings = []
    for character_class in config.classes:
        for profile in config.profiles:
            cumulative_previous = {field: 0.0 for field in DELTA_FIELDS}
            previous_transition = None
            for level_item in levels:
                current = level_item["groups"][character_class][profile]
                transition = _delta(current, cumulative_previous)
                entry = {
                    "class": character_class,
                    "profile": profile,
                    "from_level": level_item["target_level"] - 1,
                    "to_level": level_item["target_level"],
                    "incremental": transition,
                    "cumulative": {field: current.get(field, 0.0) for field in DELTA_FIELDS},
                }
                transitions.append(entry)

                if previous_transition is not None:
                    reasons = []
                    death_pp = transition["mean_deaths"] - previous_transition["mean_deaths"]
                    battle_change = _percentage_change(
                        transition["mean_battles"], previous_transition["mean_battles"]
                    )
                    city_change = transition["mean_city_visits"] - previous_transition["mean_city_visits"]
                    elapsed_change = _percentage_change(
                        transition["mean_elapsed_hours"], previous_transition["mean_elapsed_hours"]
                    )
                    if death_pp >= 0.05:
                        reasons.append(f"incremental deaths +{death_pp:.2f}")
                    if battle_change is not None and battle_change >= 25:
                        reasons.append(f"incremental battles +{battle_change:.1f}%")
                    if elapsed_change is not None and elapsed_change >= 25:
                        reasons.append(f"incremental elapsed time +{elapsed_change:.1f}%")
                    if city_change >= 2:
                        reasons.append(f"incremental city visits +{city_change:.2f}")
                    if reasons:
                        findings.append(
                            {
                                "severity": "REVIEW",
                                "code": "progression_wall",
                                "class": character_class,
                                "profile": profile,
                                "from_level": entry["from_level"],
                                "to_level": entry["to_level"],
                                "reasons": reasons,
                                "current_transition": transition,
                                "previous_transition": previous_transition,
                            }
                        )
                previous_transition = transition
                cumulative_previous = current

    return {
        "schema": "rom.simulation.progression_walls.v2",
        "version": "13.7.2",
        "methodology": "incremental transition deltas, not cumulative totals",
        "target_level": config.target_level,
        "levels": levels,
        "transitions": transitions,
        "findings": findings,
        "database_writes": 0,
    }

def _tick_start(self, actor: BattleActor, actions: List[BattleAction], turn: int):
        for key in list(actor.cooldowns): actor.cooldowns[key]=max(0,actor.cooldowns[key]-1)
        if actor.resource_type in {"combat_energy","combat_energy_combo"}: actor.resource=min(actor.max_resource,actor.resource+20)
        for key in list(actor.effects):
            e=actor.effects[key]
            if e.get("type")=="dot" and actor.alive:
                dmg=min(actor.hp,int(e.get("damage",0))); actor.hp-=dmg
                actions.append(BattleAction(turn,"effect",key,damage=dmg,details={"target":actor.name}))
            elif e.get("type")=="hot" and actor.alive:
                heal=min(actor.max_hp-actor.hp,int(e.get("heal",0))); actor.hp+=heal
                actions.append(BattleAction(turn,"effect",key,healing=heal,details={"target":actor.name}))
            e["turns"]=int(e.get("turns",0))-1
            if e["turns"]<=0: del actor.effects[key]

def _effective_skill_cost(self, actor: BattleActor, skill: Dict[str,Any]) -> int:
        """Return canonical Mana cost or the unchanged physical-resource cost."""
        if str(skill.get("cost_type") or "") == "mana":
            return calculate_mana_skill_cost(skill, actor.max_resource)
        return max(0, int(skill.get("cost", 0) or 0))

def _can_use(self, actor: BattleActor, skill: Dict[str,Any]) -> bool:
        if actor.cooldowns.get(skill["key"],0)>0: return False
        typ=skill["cost_type"]; cost=self._effective_skill_cost(actor, skill)
        if typ=="rage_all_min": return actor.resource>=int(skill.get("min_cost",30))
        if typ=="combat_energy_combo": return actor.resource>=cost and actor.combo>=int(skill.get("min_combo",1))
        return actor.resource>=cost

def _pay(self, actor: BattleActor, skill: Dict[str,Any]) -> Dict[str,int]:
        typ=skill["cost_type"]; cost=self._effective_skill_cost(actor, skill); spent={"rage":0,"combo":0}
        if typ=="rage_all_min": spent["rage"]=actor.resource; actor.resource=0
        else: actor.resource=max(0,actor.resource-cost)
        if typ=="combat_energy_combo": spent["combo"]=actor.combo; actor.combo=0
        return spent

def _apply_effect(self, player: BattleActor, mob: BattleActor, skill: Dict[str,Any], damage: int):
        effect=skill.get("effect")
        if effect=="enemy_pdef_down": mob.effects["warrior_pdef"]={"turns":3,"pdef_percent":-30}
        elif effect=="enemy_pdef_trap": mob.effects["scout_pdef"]={"turns":2,"pdef_percent":-50}
        elif effect in {"enemy_bleed","enemy_poison"}: mob.effects[effect]={"type":"dot","turns":3,"damage":max(2,int(round(max(1,damage)*.30)))}
        elif effect=="player_shield": player.effects["knight_shield"]={"type":"shield","turns":3,"absorb_left":max(15,int(player.pdef*2+player.level*3))}
        elif effect=="player_hot": player.effects["priest_hot"]={"type":"hot","turns":PRIEST_HEALING_DURATION_TURNS,"heal":max(5,int(round(player.max_hp*.10)))}
        elif effect=="restore_mana_percent": player.resource=min(player.max_resource,player.resource+calculate_mana_restore_amount(player.max_resource,skill.get("restore_max_mp_percent",25)))
        elif effect=="player_cleanse_mdef_buff":
            player.effects={k:v for k,v in player.effects.items() if not v.get("negative")}; player.effects["priest_mdef"]={"turns":3,"mdef_percent":30}
            player.resource=min(player.max_resource,player.resource+calculate_mana_restore_amount(player.max_resource,skill.get("restore_max_mp_percent",15)))

def _player_action(self, turn, class_key, p, m, actions):
        skill=self._choose(class_key,p,m)
        if skill:
            spent=self._pay(p,skill); mult=float(skill.get("damage_multiplier",0)); damage=0; crit=False
            if mult>0:
                attack=p.magic_attack if skill["attack_type"]=="magical" else p.attack
                base=call_rule("player_attack",attack,self._effective_def(m,skill["attack_type"]),p.dex,p.wis,p.level,skill["attack_type"],p.weapon_min_damage,p.weapon_max_damage,rng=self.rng)
                damage=max(1,int(round(int(base["damage"])*mult))); crit=bool(base["is_crit"])
                if skill.get("scales_with_spent_rage"): damage=max(1,int(round(damage*(1+spent["rage"]/100))))
                if skill.get("scales_with_combo"): damage=max(1,int(round(damage*(1+spent["combo"]*.50))))
                if skill.get("scales_with_player_pdef"): damage+=max(1,int(round(p.pdef*.50)))
                m.hp=max(0,m.hp-damage)
            if int(skill.get("stun_chance",0)) and self.rng.randint(1,100)<=int(skill["stun_chance"]): m.effects["stunned"]={"turns":1,"stun":True}
            if int(skill.get("combo_gain",0)): p.combo=min(p.max_combo,p.combo+int(skill["combo_gain"]))
            if int(skill.get("extra_rage",0)): p.resource=min(p.max_resource,p.resource+int(skill["extra_rage"]))
            p.cooldowns[skill["key"]]=int(skill.get("cooldown",0)); self._apply_effect(p,m,skill,damage)
            actions.append(BattleAction(turn,"player",skill["key"],damage=damage,critical=crit,details={"resource":p.resource,"combo":p.combo})); return
        kind=resolve_basic_attack_type(class_key); attack=p.magic_attack if kind=="magical" else p.attack
        raw=call_rule("player_attack",attack,self._effective_def(m,kind),p.dex,p.wis,p.level,kind,p.weapon_min_damage,p.weapon_max_damage,rng=self.rng)
        damage=int(raw["damage"]); m.hp=max(0,m.hp-damage)
        if p.resource_type=="rage": p.resource=min(p.max_resource,p.resource+15)
        actions.append(BattleAction(turn,"player","basic_attack",damage=damage,critical=bool(raw["is_crit"])))

def clamp(self):
        self.hp=max(0,min(int(self.hp),int(self.max_hp)))
        self.mp=max(0,min(int(self.mp),int(self.max_mp)))

def apply_death(self) -> None:
        self.hp=1
        self.mp=self.max_mp

def equipped_items(self):
        ids={value for value in self.equipment.slots.values() if value is not None}
        return [item for item in self.inventory.items if item.simulation_item_id in ids]

def damage_on_death(self) -> DurabilityResult:
        changed=[];broken=0
        for item in self.equipped_items():
            old=item.durability;item.durability=max(0,old-5)
            if item.durability!=old:changed.append(item.simulation_item_id)
            if old>0 and item.durability==0:broken+=1
        return DurabilityResult(len(changed),broken,changed)

def urgent_repair(self, gold: float, threshold: int=15) -> tuple[float,RepairResult]:
        candidates=[item for item in self.equipped_items() if item.durability<=int(threshold)]
        repaired=[];cost=0.0;skipped=0
        for item in sorted(candidates,key=lambda x:x.simulation_item_id):
            item_cost=float(call_rule("repair_cost",item.durability,item.rarity))
            if gold+1e-9 < item_cost:
                skipped+=1;continue
            gold=round(gold-item_cost,2);cost=round(cost+item_cost,2);item.durability=100;repaired.append(item.simulation_item_id)
        return gold,RepairResult(len(repaired),cost,skipped,repaired)

def calculate_max_hp(*, base_hp=0, stamina_hp=0, equipment_hp=0, refinement_hp=0) -> int:
    """Combine already-calculated HP components without redefining HP scaling."""
    return _whole_non_negative(
        _number(base_hp) + _number(stamina_hp) + _number(equipment_hp) + _number(refinement_hp)
    )

def _calculate_weighted_attack(character_class, matrix, *, strength=0, dexterity=0, intelligence=0, wisdom=0, stamina=0) -> int:
    class_key = str(character_class or "").strip().casefold()
    coefficients = matrix.get(class_key)
    if coefficients is None:
        return 0
    stats = {
        "str": _number(strength),
        "dex": _number(dexterity),
        "int": _number(intelligence),
        "wis": _number(wisdom),
        "sta": _number(stamina),
    }
    raw = sum(stats[key] * coefficients[key] for key in PRIMARY_STAT_KEYS)
    return max(1, int(raw))

def calculate_physical_defense(*, equipment_pdef=0, stamina=0) -> int:
    """Stage 18.14.2: active item PDEF plus total STA at coefficient 0.35."""
    from data.defense_policy import calculate_total_defense

    return int(calculate_total_defense(equipment_pdef, stamina))

def calculate_magical_defense(*, equipment_mdef=0, wisdom=0) -> int:
    """Stage 18.14.2: active item MDEF plus total WIS at coefficient 0.35."""
    from data.defense_policy import calculate_total_defense

    return int(calculate_total_defense(equipment_mdef, wisdom))

def calculate_max_mp(character_class, *, level=0, intelligence=0, wisdom=0) -> int:
    """Return configurable maximum mana for mana classes."""
    class_key = str(character_class or "").strip().casefold()
    if class_key not in MANA_CLASSES:
        return 0
    raw = (
        MAX_MP_SCALING["base"]
        + _number(level) * MAX_MP_SCALING["level"]
        + _number(intelligence) * MAX_MP_SCALING["int"]
        + _number(wisdom) * MAX_MP_SCALING["wis"]
    )
    return max(0, int(raw))

def evaluate_story_boss_invocation(state: StoryBossInvocationState) -> StoryBossInvocationDecision:
    if state.quest_number not in SUPPORTED_STORY_BOSS_QUESTS:
        return StoryBossInvocationDecision.WRONG_QUEST
    if str(state.quest_status).upper() != "ACTIVE":
        return StoryBossInvocationDecision.QUEST_NOT_ACTIVE
    if state.progress_current >= state.progress_target:
        return StoryBossInvocationDecision.ALREADY_DEFEATED
    if state.current_location_id != state.expected_location_id:
        return StoryBossInvocationDecision.WRONG_LOCATION
    if state.has_active_encounter:
        return StoryBossInvocationDecision.ACTIVE_ENCOUNTER
    if state.has_active_travel:
        return StoryBossInvocationDecision.ACTIVE_TRAVEL
    if state.is_busy:
        return StoryBossInvocationDecision.BUSY
    return StoryBossInvocationDecision.ALLOW

def process_rng_boss_story_completion(
    *,
    user_id: int,
    mob: dict,
    location_id: str,
    encounter_id,
    registry: Mapping[str, StoryQuestDefinition] = STORY_QUEST_REGISTRY,
    connection=None,
) -> dict:
    """Record a matching ACTIVE BOSS victory without completing the quest.

    Combat reward ownership remains in the combat pipeline. This bridge only
    advances the canonical BOSS objective to its bounded target. The quest stays
    ACTIVE, reward_claimed stays unchanged, and the NPC completion owner later
    completes and rewards the quest after the player reports the victory.

    Repeated delivery of the same terminal victory is idempotent because bounded
    progress is set to the same target. Defeat and escape never call this victory
    bridge, so they leave progress unchanged and allow another invocation.
    """
    if not registry:
        return {"advanced": False, "completed": False, "reason": "no_production_content"}
    if not bool((mob or {}).get("is_boss")):
        return {"advanced": False, "completed": False, "reason": "not_boss"}
    if connection is None:
        import db
        connection = db.conn

    active = get_active_story_quest(connection, int(user_id))
    if active is None:
        return {"advanced": False, "completed": False, "reason": "no_active_quest"}

    quest = registry.get(str(active["quest_id"]))
    if quest is None:
        return {"advanced": False, "completed": False, "reason": "unknown_quest_definition"}
    if quest.quest_type is not QuestType.BOSS:
        return {"advanced": False, "completed": False, "reason": "objective_type_mismatch"}
    if quest.location_id != str(location_id):
        return {"advanced": False, "completed": False, "reason": "location_mismatch"}
    if str(quest.boss_key) != str((mob or {}).get("boss_key") or ""):
        return {"advanced": False, "completed": False, "reason": "boss_key_mismatch"}

    before = int(active["progress"])
    target = int(quest.target_quantity)
    if before >= target:
        return {
            "advanced": False,
            "completed": False,
            "reason": "already_recorded",
            "quest_id": quest.quest_id,
            "progress": before,
            "target_quantity": target,
            "encounter_id": encounter_id,
            "status": str(active["status"]),
            "reward_claimed": int(active["reward_claimed"]),
        }

    with connection:
        row = set_story_quest_progress(
            connection,
            user_id=int(user_id),
            quest_id=quest.quest_id,
            progress=target,
        )

    after = int(row["progress"])
    return {
        "advanced": after > before,
        "completed": False,
        "reason": "progress_recorded" if after > before else "already_recorded",
        "quest_id": quest.quest_id,
        "progress": after,
        "target_quantity": target,
        "encounter_id": encounter_id,
        "status": str(row["status"]),
        "reward_claimed": int(row["reward_claimed"]),
    }

def init_travel_system(db_path=None):
    conn=_connect(db_path)
    try:
        conn.executescript("""
        CREATE TABLE IF NOT EXISTS location_travels (
            id INTEGER PRIMARY KEY AUTOINCREMENT,user_id INTEGER NOT NULL,
            from_node TEXT NOT NULL,to_node TEXT NOT NULL,
            status TEXT NOT NULL DEFAULT 'active' CHECK(status IN ('active','arrived','cancelled','failed')),
            revision INTEGER NOT NULL DEFAULT 1 CHECK(revision>=1),
            started_at TEXT NOT NULL,arrival_at TEXT NOT NULL,cancelled_at TEXT,completed_at TEXT,
            created_at TEXT NOT NULL,updated_at TEXT NOT NULL,CHECK(from_node<>to_node),
            FOREIGN KEY(user_id) REFERENCES users(user_id) ON DELETE CASCADE);
        CREATE UNIQUE INDEX IF NOT EXISTS ux_location_travels_one_active_user ON location_travels(user_id) WHERE status='active';
        CREATE INDEX IF NOT EXISTS ix_location_travels_due ON location_travels(status,arrival_at,id);
        CREATE INDEX IF NOT EXISTS ix_location_travels_user_history ON location_travels(user_id,id DESC);
        """); conn.commit(); return {'success':True,'table':'location_travels'}
    finally: conn.close()

def get_active_travel(user_id, *, db_path=None):
    conn=_connect(db_path)
    try: return _row(conn.execute("SELECT * FROM location_travels WHERE user_id=? AND status='active' ORDER BY id DESC LIMIT 1",(int(user_id),)).fetchone())
    finally: conn.close()

def _availability(conn,user_id,to_node):
    user=conn.execute('SELECT current_location,level FROM users WHERE user_id=?',(int(user_id),)).fetchone()
    if not user: return {'success':False,'reason':'user_not_found'}
    source=str(user['current_location'] or CITY_NODE)
    target=str(to_node)
    if source not in WORLD_NODES: return {'success':False,'reason':'invalid_current_node','current_node':source}
    if target not in WORLD_NODES: return {'success':False,'reason':'unknown_destination'}
    if not are_adjacent(source,target): return {'success':False,'reason':'not_adjacent','from_node':source,'to_node':target}
    if target != CITY_NODE and not is_location_unlocked(target,int(user['level'] or 1)):
        return {'success':False,'reason':'location_locked','from_node':source,'to_node':target}
    return {'success':True,'from_node':source,'to_node':target,'level':int(user['level'] or 1)}

def start_travel(user_id,to_node,*,now=None,busy_checker=None,db_path=None):
    if busy_checker is not None:
        busy=busy_checker(int(user_id))
        if busy: return {'success':False,'reason':'player_busy','busy':busy if isinstance(busy,dict) else None}
    current=_utc(now); stamp=_iso(current); arrival=_iso(current+timedelta(seconds=TRAVEL_SECONDS))
    conn=_connect(db_path)
    try:
        conn.execute('BEGIN IMMEDIATE')
        available=_availability(conn,user_id,to_node)
        if not available['success']: conn.rollback(); return available
        active=conn.execute("SELECT * FROM location_travels WHERE user_id=? AND status='active'",(int(user_id),)).fetchone()
        if active: conn.rollback(); return {'success':False,'reason':'already_travelling','travel':dict(active)}
        cur=conn.execute("INSERT INTO location_travels(user_id,from_node,to_node,status,revision,started_at,arrival_at,created_at,updated_at) VALUES (?,?,?,'active',1,?,?,?,?)",
            (int(user_id),available['from_node'],available['to_node'],stamp,arrival,stamp,stamp))
        travel_id=int(cur.lastrowid); conn.commit()
        return {'success':True,'travel_id':travel_id,'from_node':available['from_node'],'to_node':available['to_node'],'started_at':stamp,'arrival_at':arrival,'travel_seconds':TRAVEL_SECONDS,'revision':1}
    except sqlite3.IntegrityError:
        conn.rollback(); return {'success':False,'reason':'already_travelling'}
    except Exception: conn.rollback(); raise
    finally: conn.close()

def cancel_travel(user_id,travel_id,*,expected_revision=None,now=None,db_path=None):
    stamp=_iso(now); conn=_connect(db_path)
    try:
        conn.execute('BEGIN IMMEDIATE')
        params=[stamp,stamp,int(travel_id),int(user_id)]; where="id=? AND user_id=? AND status='active' AND arrival_at>?"; params.append(stamp)
        if expected_revision is not None: where+=' AND revision=?'; params.append(int(expected_revision))
        cur=conn.execute(f"UPDATE location_travels SET status='cancelled',revision=revision+1,cancelled_at=?,updated_at=? WHERE {where}",params)
        if cur.rowcount==1: conn.commit(); return {'success':True,'status':'cancelled','travel_id':int(travel_id)}
        row=conn.execute('SELECT * FROM location_travels WHERE id=? AND user_id=?',(int(travel_id),int(user_id))).fetchone(); conn.rollback()
        return {'success':False,'reason':'not_cancellable','travel':_row(row)}
    except Exception: conn.rollback(); raise
    finally: conn.close()

def complete_travel(travel_id,*,now=None,db_path=None):
    stamp=_iso(now); conn=_connect(db_path)
    try:
        conn.execute('BEGIN IMMEDIATE')
        row=conn.execute('SELECT * FROM location_travels WHERE id=?',(int(travel_id),)).fetchone()
        if not row: conn.rollback(); return {'success':False,'reason':'travel_not_found'}
        if row['status']!='active': conn.rollback(); return {'success':False,'reason':'already_terminal','travel':dict(row)}
        if row['arrival_at']>stamp: conn.rollback(); return {'success':False,'reason':'not_due','travel':dict(row)}
        user=conn.execute('SELECT current_location FROM users WHERE user_id=?',(int(row['user_id']),)).fetchone()
        if not user or str(user['current_location'] or CITY_NODE)!=str(row['from_node']):
            conn.execute("UPDATE location_travels SET status='failed',revision=revision+1,completed_at=?,updated_at=? WHERE id=? AND status='active'",(stamp,stamp,int(travel_id))); conn.commit()
            return {'success':False,'reason':'source_changed','status':'failed'}
        cur=conn.execute("UPDATE location_travels SET status='arrived',revision=revision+1,completed_at=?,updated_at=? WHERE id=? AND status='active'",(stamp,stamp,int(travel_id)))
        if cur.rowcount!=1: conn.rollback(); return {'success':False,'reason':'terminal_claim_lost'}
        updated=conn.execute('UPDATE users SET current_location=? WHERE user_id=? AND current_location=?',(str(row['to_node']),int(row['user_id']),str(row['from_node'])))
        if updated.rowcount!=1: raise RuntimeError('atomic location update failed')
        conn.commit(); return {'success':True,'status':'arrived','travel_id':int(travel_id),'user_id':int(row['user_id']),'from_node':row['from_node'],'to_node':row['to_node']}
    except Exception: conn.rollback(); raise
    finally: conn.close()

def recover_due_travels(*,now=None,limit=100,db_path=None):
    results=[]
    for travel in get_due_active_travels(now=now,limit=limit,db_path=db_path): results.append(complete_travel(travel['id'],now=now,db_path=db_path))
    return {'success':True,'processed':len(results),'results':results}

def _arrival_keyboard(node_id):
    from keyboards import city_kb, main_kb
    return city_kb() if str(node_id)==CITY_NODE else main_kb()

def _send_arrival(bot,result):
    try:
        from handlers.map import build_map_inline_kb
        route=get_route_presentation(result["from_node"],result["to_node"])
        text=("✅ Подорож завершено\n\n"+f"{format_arrival_destination(result['to_node'],WORLD_NODES)}\n\n"+f"{route['arrival']}")
        bot.send_message(int(result['user_id']),text,reply_markup=_arrival_keyboard(result['to_node']))
        bot.send_message(int(result['user_id']),"🗺️ Доступні напрямки:",reply_markup=build_map_inline_kb(int(result['user_id'])))
        return True
    except Exception:
        return False

def recover_travels_after_restart(bot=None,now=None):
    recovered=recover_due_travels(now=now)
    notified=[]
    if bot is not None:
        for result in recovered['results']:
            if result.get('success') and _send_arrival(bot,result): notified.append(result['travel_id'])
    return {'success':True,'processed':recovered['processed'],'notified_travel_ids':notified,'results':recovered['results']}

def start_travel_worker(bot,interval_seconds=1.0):
    global _TRAVEL_WORKER_STARTED
    if _TRAVEL_WORKER_STARTED:return False
    _TRAVEL_WORKER_STARTED=True
    def worker():
        while True:
            try: recover_travels_after_restart(bot)
            except Exception: pass
            time.sleep(max(0.5,float(interval_seconds)))
    threading.Thread(target=worker,name='location-travel-worker',daemon=True).start();return True

def worker():
        while True:
            try: recover_travels_after_restart(bot)
            except Exception: pass
            time.sleep(max(0.5,float(interval_seconds)))

